void showScores(int arr[], int size) {
    int i;
    for (i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
}

int main() {
    int scores[5] = {90, 85, 78, 92, 88};
    showScores(scores, 3);
    return 0;
}

void addBonus(int arr[], int size) {
    int i;
    for (i = 0; i < size; i++) {
        arr[i] = arr[i] + 5;
    }
}

int main() {
    int marks[3] = {70, 80, 90};
    addBonus(marks, 3);
    return 0;
}
